topics=[
('因子挖掘与资产定价',r'alpha (?:factor|discovery|mining)|alpha(?:qcm|pareto|probe|sage|bench)|factor models?|asset pricing|predictive signals'),
('投资组合与资产配置',r'portfolios?|asset allocation|black.litterman|sharpe ratio|efficient frontier|investment polic|investesg|sustainable investment'),
('交易、市场仿真与微观结构',r'\btrading\b|stock market|financial market|order book|brokerage|market impact|market simulation|cryptocurrency|arbitrage|market states'),
('股价、波动率与金融预测',r'stock|volatility|financial forecast|earnings|macroeconomic|nowcast|financial time series|financial outcomes'),
('风险、信贷、保险与反欺诈',r'fraud|risk|credit|loans?|insurance|banking|debt collection|anti.money|operational risk'),
('金融文档、问答与数值推理',r'finqa|tat.qa|financial.*(?:reason|document|report|question|search)|numerical reason|tabular|financial text|financial statement|xbrl|fintext|finchart|edinet'),
('金融文本、事件与情感分析',r'sentiment|event|financial.*(?:text|news|knowledge)|analysts|market comments'),
('金融 Agent、大模型与评测',r'agent|llm|language model|benchmark|retrieval|domain|embedding|fincon|finsight'),
('金融数值方法与通用方法应用',r'.*')]

def tag(p):
    title=p['title'];abstract=p.get('abstract','');out=[]
    for name,rx in topics[:-1]:
        if re.search(rx,title,re.I):out.append(name)
    if not out:
        for name,rx in topics[:-1]:
            if re.search(rx,abstract,re.I):out.append(name)
            if len(out)>=2:break
    return out[:3] or [topics[-1][0]]

included={};pending=[];excluded=[]
for i,c in enumerate(candidates):
    pid=aliases.get(c['id'],c['id']);p=by_id.get(pid)
    if i in core or i in applications:
        if not p:
            pending.append({'review_index':i,'id':c['id'],'title':c['title'],'reason':'universe alias unresolved'});continue
        scope='core' if i in core else 'application'
        sentences=c.get('finance_sentences',[])
        evidence=' / '.join(sentences)
        info={'review_index':i,'scope':scope,'topics':tag(p),'evidence_excerpt':evidence,
              'evidence_url':p.get('abstract_source') or p['paper_url'],
              'review_basis':'assistant review of official title/abstract; full-text verification recorded separately',
              'relevance_zh':('以金融任务或金融数据为核心研究对象。' if scope=='core' else '通用方法在金融任务、数据或明确案例上开展应用验证。')}
        included[pid]=info
    elif i in false:
        excluded.append({'review_index':i,'id':c['id'],'title':c['title'],'reason_zh':false[i]})
    else:
        pending.append({'review_index':i,'id':c['id'],'venue':c['venue'],'year':c['year'],'title':c['title'],
                        'reason_zh':'关键词命中；尚无足够依据认定实际金融任务或应用实验。常见情况是背景举例、成本表述、通用权衡或非金融意义。',
                        'abstract':c.get('abstract',''),'paper_url':c.get('paper_url','')})
save_json('checks/finance_review.json',{'included':included,'excluded':excluded,'pending':pending,
    'counts':{'core':sum(i['scope']=='core' for i in included.values()),'application':sum(i['scope']=='application' for i in included.values()),'pending':len(pending),'explicit_false_positives':len(excluded)},
    'snapshot_sha256':hashlib.sha256((ROOT/'checks/finance_candidates.json').read_bytes()).hexdigest()})
print('Finance review',len(included),Counter(x['scope'] for x in included.values()),'pending',len(pending),flush=True)
